// Sunrise: a warm band climbs the helix, sky warms from cyan to peach,
// base flares once the front passes. All per-LED maths in fixed point.
uniform float speed   : 0.05 .. 2.0 = 0.35;   // climb rate (cycles per second)
uniform float width   : 0.02 .. 0.5  = 0.15;  // glow band width (fraction of height)
uniform float sat     : 0.0 .. 1.0   = 0.55;  // sky saturation
uniform float bright  : 0.0 .. 2.0   = 1.0;   // overall gain

state fixed climb;   // band position in turns
state fixed w;       // width, fixed
state fixed s;       // saturation, fixed
state fixed g;       // gain, fixed

void update() {
  climb = fract(climb + fixed(dt * speed));
  w = fixed(width);
  s = fixed(sat);
  g = fixed(bright);
}

vec3 shade(Led led) {
  fixed h = fixed(led.pos.y) * fixed(3.3333);   // 0..1 up the lamp
  fixed f = fract(climb * fixed(1.5) - h * fixed(0.5));  // 1 at the front
  fixed d = fixed(1.0) - f;                      // signed distance, front = 0
  fixed band = clamp(f * (fixed(1.0) / w), fixed(0.0), fixed(1.0));
  fixed base = clamp(d * fixed(1.25), fixed(0.0), fixed(1.0));
  fixed hf = clamp((h - fixed(0.75)) * fixed(4.0), fixed(0.0), fixed(1.0));
  fixed hue = fixed(0.055) + base * fixed(0.035) + hf * fixed(0.09);
  fixed val = band * (fixed(0.4) + base * fixed(0.6));
  return hsv2rgb(hue, s, val) * g;
}

